svg.script:
(function() {
  var activeFloor = 1;
  var activeExam = 'rm';

  var dataStore = {
    1: {
      name: "1º NMS (Corticoespinal)",
      sub: "Córtex Motor / Tronco / Medula",
      rm: {
        status: "success",
        badge: "✓ INDICAÇÃO PERFEITA",
        title: "1º NMS × RM/TC Crânio-Medular",
        desc: "O 1º NMS situa-se inteiramente no SNC. A RM ou TC de Encéfalo/Medula é o exame de escolha para diagnosticar lesões estruturais (AVC, desmielinização, tumores, mielopatias).",
        alert: "Exame de Ouro! Visualiza parênquima cerebral e medular com alta resolução.",
        alertColor: "var(--fm1p11-green, #10b981)",
        caseTitle: "Hemiparesia espástica + Babinski (+)",
        caseAction: "Conduta: Solicitar RM de Encéfalo. Lesão de 1º NMS no SNC."
      },
      enmg: {
        status: "warning",
        badge: "⚠️ FORA DE INDICAÇÃO",
        title: "1º NMS × Eletroneuromiografia",
        desc: "A ENMG avalia estritamente o Sistema Nervoso Periférico (a partir do corno anterior da medula). Não é capaz de avaliar tratos corticoespinais centrais.",
        alert: "A ENMG estará NORMAL ou com alterações inespecíficas de via central.",
        alertColor: "var(--fm1p11-amber, #f59e0b)",
        caseTitle: "Suspeita de Mielopatia ou AVC",
        caseAction: "Erro de Solicitação: ENMG não avalia 1º NMS. Troque por Neuroimagem (RM/TC)."
      }
    },
    2: {
      name: "2º NMI (Nervo Periférico)",
      sub: "Corno Anterior / Raiz / Plexo / Nervo",
      rm: {
        status: "error",
        badge: "❌ ERRO CLÁSSICO DE PROVA!",
        title: "2º NMI × RM de Crânio Default",
        desc: "Solicitar RM de Crânio para lesão de 2º NMI (ex: Guillain-Barré, polineuropatias, radiculopatias) é um erro comum de prática. A RM de Crânio virá NORMAL!",
        alert: "Desperdício de recurso e atraso diagnóstico! O foco é o SNP.",
        alertColor: "var(--fm1p11-coral, #f43f5e)",
        caseTitle: "Tetraparesia flácida arreflexa ascendente (GBS)",
        caseAction: "ERRO GRAVE: Pedir RM crânio! O exame correto de rastreio/confirmação é a ENMG."
      },
      enmg: {
        status: "success",
        badge: "✓ INDICAÇÃO PERFEITA",
        title: "2º NMI × Eletroneuromiografia",
        desc: "A ENMG é o padrão-ouro para avaliar a integridade do 2º NMI: estuda condução nervosa motora/sensitiva e sinais de desnervação no músculo por agulha.",
        alert: "Diferencia neuropatia axonal vs desmielinizante, radiculopatia e ELA.",
        alertColor: "var(--fm1p11-green, #10b981)",
        caseTitle: "Paresia distal simétrica com arreflexia",
        caseAction: "Conduta Correta: Solicitar ENMG (Estudo de Condução + Agulha)."
      }
    },
    3: {
      name: "Placa Neuromuscular",
      sub: "Junção Mioneural (Pré/Pós-sináptica)",
      rm: {
        status: "error",
        badge: "❌ ERRO CLÁSSICO DE PROVA!",
        title: "Placa Neuromuscular × RM Crânio",
        desc: "Em quadros de fatigabilidade muscular, ptose palpebral ou diplopia (ex: Miastenia Gravis, Botulismo), a RM de crânio estará completamente NORMAL.",
        alert: "A RM de crânio não enxerga a fenda sináptica nem os receptores de ACh!",
        alertColor: "var(--fm1p11-coral, #f43f5e)",
        caseTitle: "Ptose palpebral flutuante que piora ao final do dia",
        caseAction: "ERRO: Pedir RM crânio. O correto é ENMG com estimulação repetitiva."
      },
      enmg: {
        status: "success",
        badge: "✓ INDICAÇÃO PERFEITA",
        title: "Placa Neuromuscular × ENMG",
        desc: "A ENMG com Estimulação Repetitiva de Freqüência (ou Fibra Única) demonstra decremento (Miastenia) ou incremento (Lambert-Eaton) da resposta motora.",
        alert: "Padrão de Ouro para confirmar disfunção da junção neuromuscular!",
        alertColor: "var(--fm1p11-green, #10b981)",
        caseTitle: "Fatigabilidade muscular + Anti-AChR (+)",
        caseAction: "Conduta Correta: Solicitar ENMG com Teste de Estimulação Repetitiva."
      }
    },
    4: {
      name: "Músculo Esquelético",
      sub: "Fibra Miógena / Sarcolema",
      rm: {
        status: "error",
        badge: "❌ ERRO CLÁSSICO DE PROVA!",
        title: "Músculo × RM de Crânio Default",
        desc: "Miopatias causam fraqueza muscular proximal simétrica (ex: Polimiosite, Distrofias). A RM de crânio não avalia o tecido muscular periférico acometido.",
        alert: "RM de crânio normal não exclui miopatia grave!",
        alertColor: "var(--fm1p11-coral, #f43f5e)",
        caseTitle: "Dificuldade para subir escadas + CPK elevada",
        caseAction: "ERRO: Solicitar RM crânio. A investigação exige ENMG e/ou biópsia muscular."
      },
      enmg: {
        status: "success",
        badge: "✓ INDICAÇÃO PERFEITA",
        title: "Músculo Esquelético × ENMG",
        desc: "A ENMG de agulha caracteriza o Padrão Miopático: potenciais de ação de unidade motora (PAMUs) de curta duração, baixa amplitude e recrutamento precoce.",
        alert: "Confirma o comprometimento miógeno e guia o local ideal para biópsia!",
        alertColor: "var(--fm1p11-green, #10b981)",
        caseTitle: "Fraqueza de cintura pélvica/escapular + mialgia",
        caseAction: "Conduta Correta: Solicitar ENMG de Agulha (Padrão Miógeno)."
      }
    }
  };

  function updateView() {
    // Update floor button styles
    for (var i = 1; i <= 4; i++) {
      var btn = document.getElementById('fm1p11-btn-f' + i);
      if (btn) {
        if (i === activeFloor) {
          btn.classList.add('fm1p11-active');
        } else {
          btn.classList.remove('fm1p11-active');
        }
      }
    }

    // Update exam button styles
    var btnRm = document.getElementById('fm1p11-btn-rm');
    var btnEnmg = document.getElementById('fm1p11-btn-enmg');
    if (btnRm && btnEnmg) {
      if (activeExam === 'rm') {
        btnRm.classList.add('fm1p11-active');
        btnEnmg.classList.remove('fm1p11-active');
      } else {
        btnRm.classList.remove('fm1p11-active');
        btnEnmg.classList.add('fm1p11-active');
      }
    }

    // Fetch data
    var floorData = dataStore[activeFloor];
    var config = floorData[activeExam];

    // Update Central Flow Nodes
    var txtFloor1 = document.getElementById('fm1p11-node-floor-txt1');
    var txtFloor2 = document.getElementById('fm1p11-node-floor-txt2');
    var txtExam1 = document.getElementById('fm1p11-node-exam-txt1');
    var txtExam2 = document.getElementById('fm1p11-node-exam-txt2');

    if (txtFloor1) txtFloor1.textContent = "Andar " + activeFloor;
    if (txtFloor2) txtFloor2.textContent = floorData.name.split(' ')[0] + " " + (floorData.name.split(' ')[1] || '');
    if (txtExam1) txtExam1.textContent = (activeExam === 'rm' ? 'RM/TC SNC' : 'ENMG');
    if (txtExam2) txtExam2.textContent = (activeExam === 'rm' ? 'Neuroimagem' : 'Eletroneuro');

    // Flow Line and Badge Colors
    var flowPath = document.getElementById('fm1p11-flow-path');
    var flowStatusBg = document.getElementById('fm1p11-flow-status-bg');
    var flowStatusTxt = document.getElementById('fm1p11-flow-status-txt');

    var cardBadgeBg = document.getElementById('fm1p11-card-badge-bg');
    var cardBadgeTxt = document.getElementById('fm1p11-card-badge-txt');

    var strokeColor = "var(--fm1p11-green, #10b981)";
    var markerEnd = "url(#fm1p11-arrow-green)";
    var badgeClass = "fm1p11-badge-success";

    if (config.status === 'error') {
      strokeColor = "var(--fm1p11-coral, #f43f5e)";
      markerEnd = "url(#fm1p11-arrow-red)";
      badgeClass = "fm1p11-badge-error";
    } else if (config.status === 'warning') {
      strokeColor = "var(--fm1p11-amber, #f59e0b)";
      markerEnd = "url(#fm1p11-arrow-amber)";
      badgeClass = "fm1p11-badge-warning";
    }

    if (flowPath) {
      flowPath.setAttribute('stroke', strokeColor);
      flowPath.setAttribute('marker-end', markerEnd);
    }

    if (flowStatusBg) flowStatusBg.setAttribute('class', badgeClass);
    if (flowStatusTxt) {
      flowStatusTxt.textContent = config.badge;
      flowStatusTxt.setAttribute('fill', strokeColor);
    }

    if (cardBadgeBg) cardBadgeBg.setAttribute('class', badgeClass);
    if (cardBadgeTxt) {
      cardBadgeTxt.textContent = config.badge;
      cardBadgeTxt.setAttribute('fill', strokeColor);
    }

    // Update Right Panel Content
    var cardTitle = document.getElementById('fm1p11-card-title');
    var cardDesc = document.getElementById('fm1p11-card-desc');
    var cardAlert = document.getElementById('fm1p11-card-alert');
    var caseText = document.getElementById('fm1p11-case-text');
    var caseAction = document.getElementById('fm1p11-case-action');

    if (cardTitle) cardTitle.textContent = config.title;
    if (cardDesc) cardDesc.innerHTML = config.desc;
    if (cardAlert) {
      cardAlert.textContent = config.alert;
      cardAlert.style.color = config.alertColor;
    }

    if (caseText) caseText.innerHTML = "<strong>Cenário:</strong> " + config.caseTitle;
    if (caseAction) {
      caseAction.innerHTML = "<strong>Resultado / Conduta:</strong> " + config.caseAction;
      caseAction.style.color = strokeColor;
    }
  }

  // Event Listeners for Floor Buttons
  [1, 2, 3, 4].forEach(function(f) {
    var btn = document.getElementById('fm1p11-btn-f' + f);
    if (btn) {
      btn.addEventListener('click', function() {
        activeFloor = f;
        updateView();
      });
      btn.addEventListener('keydown', function(e) {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          activeFloor = f;
          updateView();
        }
      });
    }
  });

  // Event Listeners for Exam Buttons
  var btnRm = document.getElementById('fm1p11-btn-rm');
  if (btnRm) {
    btnRm.addEventListener('click', function() {
      activeExam = 'rm';
      updateView();
    });
    btnRm.addEventListener('keydown', function(e) {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        activeExam = 'rm';
        updateView();
      }
    });
  }

  var btnEnmg = document.getElementById('fm1p11-btn-enmg');
  if (btnEnmg) {
    btnEnmg.addEventListener('click', function() {
      activeExam = 'enmg';
      updateView();
    });
    btnEnmg.addEventListener('keydown', function(e) {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        activeExam = 'enmg';
        updateView();
      }
    });
  }

  // Tooltip Engine
  var svg = document.getElementById('fm1p11-svg');
  var tooltip = document.getElementById('fm1p11-tooltip');
  var tooltipTxt = document.getElementById('fm1p11-tooltip-txt');
  var tooltipRect = document.getElementById('fm1p11-tooltip-rect');

  function showTooltip(evt, text) {
    if (!tooltip || !svg) return;
    tooltipTxt.textContent = text;
    var bbox = tooltipTxt.getBBox();
    tooltipRect.setAttribute('width', bbox.width + 20);

    var pt = svg.createSVGPoint();
    pt.x = evt.clientX;
    pt.y = evt.clientY;
    var cursor = pt.matrixTransform(svg.getScreenCTM().inverse());

    tooltip.setAttribute('transform', 'translate(' + (cursor.x + 12) + ',' + (cursor.y + 12) + ')');
    tooltip.setAttribute('visibility', 'visible');
  }

  function hideTooltip() {
    if (tooltip) tooltip.setAttribute('visibility', 'hidden');
  }

  // Tooltip triggers
  [
    { id: 'fm1p11-btn-f1', text: 'Andar 1: Córtex e Mielopatias → Neuroimagem' },
    { id: 'fm1p11-btn-f2', text: 'Andar 2: Corno Anterior e Nervos → ENMG' },
    { id: 'fm1p11-btn-f3', text: 'Andar 3: Miastenia / Botulismo → ENMG Estimulação Repetitiva' },
    { id: 'fm1p11-btn-f4', text: 'Andar 4: Miopatias → ENMG Padrão Miógeno' },
    { id: 'fm1p11-btn-rm', text: 'RM/TC: Exame de Escolha para SNC' },
    { id: 'fm1p11-btn-enmg', text: 'ENMG: Exame de Escolha para SNP / Placa / Músculo' }
  ].forEach(function(item) {
    var el = document.getElementById(item.id);
    if (el) {
      el.addEventListener('mousemove', function(e) { showTooltip(e, item.text); });
      el.addEventListener('mouseleave', hideTooltip);
    }
  });

  // Initial render
  updateView();
})();
